Looking at the current code, I need to apply double buffering to overlap the load and compute phases in the load phase (tiling loop), and similarly for the store phase. The key idea is: while computing on tile k, load tile k+1 simultaneously.

For the Cholesky kernel, the most impactful place is the initial LOAD PHASE - I'll create ping-pong buffers so loading the next tile overlaps with copying the current tile into L. Similarly for the STORE PHASE.

```cpp
#include "cholesky.h"
#include <cmath>
#include <cstring>

#ifndef TILE
#define TILE 16
#endif

extern "C" {

// Load a tile of rows [row_start, row_start+TILE) x [0, N) into local buffer (ping-pong selected by flag)
static void load_tile_db(double tile_buf_0[TILE][N], double tile_buf_1[TILE][N],
                          double A[N][N], int row_start, int flag) {
    for (int i = 0; i < TILE; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            double val = (gi < N) ? A[gi][j] : 0.0;
            if (flag == 0)
                tile_buf_0[i][j] = val;
            else
                tile_buf_1[i][j] = val;
        }
    }
}

// Store a tile of rows [row_start, row_start+TILE) x [0, N) from local buffer (ping-pong selected by flag)
static void store_tile_db(double A[N][N],
                           double tile_buf_0[TILE][N], double tile_buf_1[TILE][N],
                           int row_start, int flag) {
    for (int i = 0; i < TILE; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            int gi = row_start + i;
            if (gi < N) {
                if (flag == 0)
                    A[gi][j] = tile_buf_0[i][j];
                else
                    A[gi][j] = tile_buf_1[i][j];
            }
        }
    }
}

void kernel_cholesky(
        double A[N + 0][N + 0])
